      type: 'string',
      required: false,
      default: 'undefined',
    },
  ],
  tokens: [
    '--cascivo-color-border-strong',
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-font-sans',
    '--cascivo-font-medium',
    '--cascivo-leading-relaxed',
